<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Access\UserPersonalApiKey\Infrastructure\Driver\Rest;

use Psr\Http\Message\ResponseInterface;
use Psr\Http\Message\ServerRequestInterface;
use OpenApi\Attributes as OA;
use Throwable;
use DateTime;
use Civi\Lughauth\Shared\Exception\NotFoundException;
use Civi\Lughauth\Shared\Observability\LoggerAwareTrait;
use Civi\Lughauth\Shared\Observability\TracerAwareTrait;
use Civi\Lughauth\Features\Access\UserPersonalApiKey\Application\Usecase\Retrieve\UserPersonalApiKeyRetrieveUsecase;
use Civi\Lughauth\Features\Access\UserPersonalApiKey\Application\Usecase\Retrieve\UserPersonalApiKeyRetrieveResult;

class UserPersonalApiKeyRetrieveController
{
    use LoggerAwareTrait;
    use TracerAwareTrait;

    public function __construct(
        private readonly UserPersonalApiKeyRetrieveUsecase $retrieveUsecase,
    ) {
    }
    #[OA\Get(
        path: "/api/access/me/api-keys{uid}",
        tags: ["User personal api key"],
        description:"Create",
        parameters: [
               new OA\PathParameter(name: "uid", required: true, schema: new OA\Schema(type: "string")),
          ],
        responses: [
              new OA\Response(response: 201, description: "Ok", content: new OA\JsonContent(type: "object", ref:"#/components/schemas/UserPersonalApiKeyApiDTO")),
              new OA\Response(response: 404, description: "Not found"),
          ]
    )]
    public function retrieve(ServerRequestInterface $request, ResponseInterface $response, array $args): ResponseInterface
    {
        $this->logDebug("Retrieve User personal api key");
        $span = $this->startSpan("Retrieve User personal api key");
        try {
            if (!isset($args['uid'])) {
                throw new NotFoundException('-');
            }
            $uid = $args['uid'];
            $result = $this->retrieveUsecase->retrieve($uid);
            $value = $this->mapUserPersonalApiKey($request, $result);
            $encoded = json_encode($value);
            $response->getBody()->write($encoded === false ? '' : $encoded);
            return $response->withStatus(200)
                  ->withHeader('Content-Type', 'application/json');
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }

    private function mapUserPersonalApiKey(ServerRequestInterface $request, UserPersonalApiKeyRetrieveResult $value): UserPersonalApiKeyApiDTO
    {
        $this->logDebug("Map entity to output dto for User personal api key");
        $span = $this->startSpan("Map entity to output dto for User personal api key");
        try {
            $user = $value->getUser();
            $dto = new UserPersonalApiKeyApiDTO();
            $dto->uid = $value->getUid();
            $dto->user = $user ? ['$ref' => $user->uid()] : null;
            $dto->name = $value->getName();
            $dto->keyHash = $value->getKeyHash();
            $dto->scopes = $value->getScopes();
            $dto->lastUsedAt = $value->getLastUsedAt()?->format(DateTime::ATOM);
            $dto->expiresAt = $value->getExpiresAt()?->format(DateTime::ATOM);
            $dto->createdAt = $value->getCreatedAt()?->format(DateTime::ATOM);
            $dto->enabled = $value->isEnabled();
            $dto->version = $value->getVersion();
            return $dto;
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
}
